import Model from 'flarum/common/Model';

/**
 * 'latest' when the advisor is dormant: there is no target to check against.
 */

/**
 * Mirrors FoF\UpgradeAdvisor\ExtensionAction.
 */

export const BLOCKING_ACTIONS = ['remove', 'swap_after_upgrade', 'switch_replacement', 'no_path'];
export const READY_ACTIONS = ['none'];
export default class Report extends Model {
  overall() {
    return Model.attribute('overall').call(this);
  }

  /**
   * The release being checked against, e.g. "3.0"; null while dormant.
   */
  target() {
    return Model.attribute('target').call(this);
  }
  checkedAt() {
    return Model.attribute('checkedAt', Model.transformDate).call(this);
  }
  dataAsOf() {
    return Model.attribute('dataAsOf', Model.transformDate).call(this);
  }
  checks() {
    return Model.attribute('checks').call(this) || [];
  }

  /**
   * The extension breakdown from the compatibility check.
   */
  extensions() {
    const check = this.checks().find(c => Array.isArray(c.meta.extensions));
    return check ? check.meta.extensions : [];
  }

  /**
   * Every check except the extension compatibility one, which has its own UI.
   */
  otherChecks() {
    return this.checks().filter(c => !Array.isArray(c.meta.extensions));
  }
}
flarum.reg.add('fof-upgrade-advisor', 'admin/models/Report', Report);